pub struct SimpleValidator {
    required_headers: Vec<String>,
    max_header_size: Option<usize>,
    header_prefixes: Vec<(String, String)>,
    max_total_headers: Option<usize>,
}

impl MetadataValidator for SimpleValidator {
    fn validate(&self, md: &MetadataMap) -> Result<(), Status> {
        // required headers
        for h in &self.required_headers {
            if !md.contains_key(h) {
                return Err(Status::failed_precondition(format!("missing header {}", h)));
            }
        }
        // max_header_size
        if let Some(limit) = self.max_header_size {
            for (name, value) in md.as_ref().iter() {
                let size = name.as_str().len() + value.as_bytes().len();
                if size > limit {
                    return Err(Status::invalid_argument(format!(
                        "header {} exceeds size limit",
                        name
                    )));
                }
            }
        }
        // header_prefix
        for (name, prefix) in &self.header_prefixes {
            if let Some(val) = md.get(name) {
                // val is MetadataValue<Ascii>, can convert to str via to_str()? There's method to_str() returning Result<&str, _>.
                // To avoid unwrap, we can match val.to_str() { Ok(s) => { if !s.starts_with(prefix) { return Err(...); } }, Err(_) => { return Err(Status::invalid_argument(...)); } }
                match val.to_str() {
                    Ok(s) => {
                        if !s.starts_with(prefix) {
                            return Err(Status::invalid_argument(format!(
                                "header {} does not start with {}",
                                name, prefix
                            )));
                        }
                    }
                    Err(_) => {
                        return Err(Status::invalid_argument(format!(
                            "header {} not ascii",
                            name
                        )));
                    }
                }
            }
        }
        // max_total_headers
        if let Some(limit) = self.max_total_headers {
            let count = md.as_ref().len();
            if count > limit {
                return Err(Status::resource_exhausted(format!(
                    "too many headers {} > {}",
                    count, limit
                )));
            }
        }
        Ok(())
    }
}

